    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # marker is a corner-shaped 9 object; recolor the 5-object in the diagonally opposite quadrant.
    # Locate the corner marker and paint the closest 5-component wholly in its open quadrant.
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==9]
    if not pts: return out
    mr=max(r for r,c in pts); mc=min(c for r,c in pts) # elbow at top-right
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=5 or (r,c) in seen: continue
       st=[(r,c)]; seen.add((r,c)); co=[]
       while st:
        y,x=st.pop(); co.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         yy,xx=y+dy,x+dx
         if 0<=yy<h and 0<=xx<w and grid[yy][xx]==5 and (yy,xx) not in seen: seen.add((yy,xx));st.append((yy,xx))
       if min(y for y,x in co)>mr and max(x for y,x in co)<mc: comps.append(co)
    if comps:
      co=min(comps,key=lambda co:min((r-mr)+(mc-c) for r,c in co))
      for r,c in co: out[r][c]=9
    return out
